package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: ZFSD_PRICE_SIMULATION / {@code ZTSD_PS_PARTNERS} / item 
 */
public class PricingCallDTOPartner implements Serializable {

	private static final long serialVersionUID = -6962922528742738155L;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / PARTN_ROLE
	 */
	private String partnerRole; // Version Number Component 
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / PARTN_NUMB
	 */
	private String partnerNumber; // Customer Number 1
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / NAME 
	 */
	private String name1;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / NAME2 
	 */
	private String name2;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / NAME3
	 */
	private String name3;	
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / STREET 
	 */
	private String street; // House number and street

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / COUNTRY
	 */
	private String country;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / POSTL_CODE
	 */
	private String postalCode;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item / CITY
	 */
	private String city;

	public String getPartnerRole() {
		return partnerRole;
	}

	public void setPartnerRole(String partnerRole) {
		this.partnerRole = partnerRole;
	}

	public String getPartnerNumber() {
		return partnerNumber;
	}

	public void setPartnerNumber(String partnerNumber) {
		this.partnerNumber = partnerNumber;
	}

	public String getName1() {
		return name1;
	}

	public void setName1(String name1) {
		this.name1 = name1;
	}

	public String getName2() {
		return name2;
	}

	public void setName2(String name2) {
		this.name2 = name2;
	}

	public String getName3() {
		return name3;
	}

	public void setName3(String name3) {
		this.name3 = name3;
	}

	public String getStreet() {
		return street;
	}

	public void setStreet(String street) {
		this.street = street;
	}

	public String getCountry() {
		return country;
	}

	public void setCountry(String country) {
		this.country = country;
	}

	public String getPostalCode() {
		return postalCode;
	}

	public void setPostalCode(String postalCode) {
		this.postalCode = postalCode;
	}

	public String getCity() {
		return city;
	}

	public void setCity(String city) {
		this.city = city;
	}

	@Override
	public String toString() {
		return "PricingCallDTOPartner [partnerRole=" + partnerRole + ", partnerNumber="
				+ partnerNumber + ", name1=" + name1 + ", name2=" + name2 + ", name3=" + name3
				+ ", street=" + street + ", country=" + country + ", postalCode=" + postalCode
				+ ", city=" + city + "]";
	}
	
}